"""Count secret hits in files/stdin. Prints labels + counts + locations only, never values."""
import re, sys, os, pathlib
ROOT = "/Users/durgapritamsuggisetti/Documents/Hackathon/neatlogs/backend"
SECRET_KEYS = {"GROQ_API_KEY","GITHUB_TOKEN","NEATLOGS_API_KEY","ADMIN_TOKEN","YOUTUBE_API_KEY"}
values = {}
for f in (".env", ".env.production"):
    p = os.path.join(ROOT, f)
    if not os.path.exists(p): continue
    for line in open(p):
        if "=" in line and not line.lstrip().startswith("#"):
            k, v = line.strip().split("=", 1)
            v = v.strip().strip('"').strip("'")
            if k in SECRET_KEYS and len(v) >= 8:
                values[f"exact:{k}({f})"] = v
# AWS credentials if present
aws = pathlib.Path.home()/".aws/credentials"
if aws.exists():
    for line in aws.read_text().splitlines():
        if "=" in line:
            k, v = [x.strip() for x in line.split("=",1)]
            if k in ("aws_access_key_id","aws_secret_access_key","aws_session_token") and len(v)>=8:
                values[f"exact:{k}"] = v
PATTERNS = {
 "groq_key": r"gsk_[A-Za-z0-9]{20,}",
 "github_pat": r"(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{40,}",
 "google_api_key": r"AIza[0-9A-Za-z_\-]{30,}",
 "aws_access_key": r"(?:AKIA|ASIA)[0-9A-Z]{16}",
 "aws_secret_assign": r"aws_secret_access_key\s*[=:]\s*[A-Za-z0-9/+]{30,}",
 "private_key": r"-----BEGIN [A-Z ]*PRIVATE KEY-----",
 "env_assign_secret": r"(?:GROQ_API_KEY|GITHUB_TOKEN|NEATLOGS_API_KEY|ADMIN_TOKEN|YOUTUBE_API_KEY)\s*=\s*['\"]?[A-Za-z0-9_\-]{12,}",
 "bearer": r"[Bb]earer\s+[A-Za-z0-9_\-\.]{24,}",
 "x_admin_token_hdr": r"X-Admin-Token:\s*[A-Za-z0-9_\-]{12,}",
}
PLACEHOLDER = re.compile(r"(?i)x{6,}|your|example|changeme|REDACTED|\.\.\.|<")
def scan(name, text, out):
    for label, v in values.items():
        c = text.count(v)
        if c: out.setdefault(label, []).append((name, c))
    for label, pat in PATTERNS.items():
        hits = [m.group(0) for m in re.finditer(pat, text)]
        hits = [h for h in hits if not PLACEHOLDER.search(h)]
        if hits: out.setdefault("pattern:"+label, []).append((name, len(hits)))
out = {}
args = sys.argv[1:]
if not args or args == ["-"]:
    scan("<stdin>", sys.stdin.read(), out)
for a in args:
    if a == "-": continue
    for p in ([a] if os.path.isfile(a) else [str(x) for x in pathlib.Path(a).rglob("*") if x.is_file()]):
        try: scan(p, open(p, errors="ignore").read(), out)
        except Exception as e: print("skip", p, type(e).__name__)
print(f"loaded {len(values)} exact secret values to match")
if not out: print("NO HITS")
for label, locs in sorted(out.items()):
    print(label, "total", sum(c for _, c in locs))
    for n, c in locs[:10]: print("   ", c, n)
EOF
