def check_dead_links(links: list[dict]) -> dict:
    title = "No dead links in README"
    dead = [f"{l['url']} ({l['status'] or l['error']})" for l in links if l["ok"] is False]
    unknown = [l["url"] for l in links if l["ok"] is None]
