"""Project history: score progress between checks and anonymous percentiles.

Progress compares an audit with the same repo's previous scored audit ("+22 since your last
check (46 → 68)") and names the checks that went to pass. Percentiles compare a score with the
cohort: the latest real audit of every repo with commits inside the hackathon window, excluding
removed audits, test runs and our own repo. Only aggregate numbers ever leave this module:
never another repo's name or score.
"""
import re
import threading
import time
from datetime import datetime, timezone

from app import config, db

MIN_COHORT = 15
COHORT_TTL_S = 600
OWN_REPO = "durgapritam/neathack-qbits-"

# key checks shown with a cohort percentage, and how a "pass" reads
KEY_CHECKS = {
    "demo_video": "a demo video under 3:00",
    "entire_checkpoints": "Entire checkpoints",
    "cfo_ai_plan": "a cfo.ai business plan",
    "before_after": "a before/after comparison with numbers",
    "failure_recovery": "a documented failure-and-recovery run",
}


def is_hackathon_repo(report: dict) -> bool:
    c = next((c for c in report.get("checks", []) if c["id"] == "commits_in_window"), None)
    m = re.match(r"(\d+) inside", (c or {}).get("detail", ""))
    return bool(m and int(m.group(1)) > 0)


def _score(result: dict | None) -> int | None:
    return ((result or {}).get("score") or {}).get("score")


def _statuses(result: dict | None) -> dict[str, tuple[str, str]]:
    return {c["id"]: (c["status"], c["title"]) for c in (result or {}).get("checks", [])}


def progress(previous: dict, result: dict) -> dict | None:
    """Score delta and fixed/regressed checks between two audits of the same repo."""
    old, new = _score(previous.get("result")), _score(result)
    if old is None or new is None:
        return None
    before, after = _statuses(previous.get("result")), _statuses(result)
    fixed = [after[k][1] for k in after if after[k][0] == "pass" and before.get(k, ("",))[0] in ("fail", "warn")]
    regressed = [after[k][1] for k in after if before.get(k, ("",))[0] == "pass" and after[k][0] in ("fail", "warn")]
    delta = new - old
    if delta > 0:
        text = f"+{delta} since your last check ({old} → {new})"
    elif delta == 0:
        text = f"Same score as your last check ({new})"
    else:
        text = f"{delta} since your last check ({old} → {new})"
    return {"previous_audit_id": previous["id"], "previous_at": previous["created_at"], "previous_score": old,
            "score": new, "delta": delta, "text": text, "fixed": fixed, "regressed": regressed}


def attach_progress(audit_id: str, repo_key: str | None, run_kind: str, created_at: str, result: dict) -> dict:
    """Add result["progress"] when this repo was checked before. Never fails the audit."""
    if not repo_key:
        return result
    try:
        prev = db.previous_audit(repo_key, created_at, audit_id, run_kind)
        p = progress(prev, result) if prev else None
    except Exception:
        p = None
    if p:
        result["progress"] = p
    else:
        result.pop("progress", None)
    return result


def record(audit_id: str, row: dict, result: dict, deep: bool) -> None:
    """Update the projects table when a phase finishes."""
    if not row.get("repo_key") or row.get("is_example"):
        return
    from app.tools.rubric import CHECKS_VERSION
    try:
        db.upsert_project(row["repo_key"], row["repo_url"], audit_id, _score(result), is_hackathon_repo(result),
                          deep=deep, deep_sha=row.get("commit_sha") if deep else None,
                          checks_version=CHECKS_VERSION, new_audit=not deep)
    except Exception:
        pass  # bookkeeping must never break an audit


# ---------------------------------------------------------------- percentiles

class Cohort:
    """Aggregate stats over the cohort, recomputed at most every COHORT_TTL_S seconds."""

    def __init__(self, ttl_s: float = COHORT_TTL_S, clock=time.monotonic):
        self.ttl_s, self.clock = ttl_s, clock
        self._at = -1e18
        self._stats: dict | None = None
        self._lock = threading.Lock()

    def invalidate(self) -> None:
        with self._lock:
            self._at = -1e18

    def stats(self) -> dict:
        with self._lock:
            if self._stats is None or self.clock() - self._at >= self.ttl_s:
                self._stats = self._compute()
                self._at = self.clock()
            return self._stats

    def _compute(self) -> dict:
        own = config.env("OWN_REPO", OWN_REPO).lower()
        rows = db.cohort_rows(own)
        scores = {r["repo_key"]: _score(r["result"]) for r in rows if _score(r["result"]) is not None}
        passes = {cid: {r["repo_key"] for r in rows if _statuses(r["result"]).get(cid, ("",))[0] == "pass"}
                  for cid in KEY_CHECKS}
        return {"size": len(scores), "scores": scores, "passes": passes,
                "computed_at": datetime.now(timezone.utc).isoformat(timespec="seconds")}


COHORT = Cohort()


def percentiles(repo_key: str | None, result: dict | None, cohort: Cohort = COHORT) -> dict | None:
    """Anonymous, positive comparisons for one audit, or None while the cohort is too small."""
    score = _score(result)
    if score is None:
        return None
    stats = cohort.stats()
    others = {k: v for k, v in stats["scores"].items() if k != (repo_key or "")}
    if len(others) < MIN_COHORT:
        return None
    beats = round(100 * sum(1 for v in others.values() if v < score) / len(others))
    mine = _statuses(result)
    checks = []
    for cid, what in KEY_CHECKS.items():
        have = stats["passes"][cid] - {repo_key}
        pct = round(100 * len(have) / len(others))
        passed = mine.get(cid, ("",))[0] == "pass"
        if passed:
            lead = "Only " if pct < 50 else ""
            text = f"{lead}{pct}% of teams have {what}. You're one of them ✅"
        else:
            text = f"{pct}% of teams already have {what}."
        checks.append({"check_id": cid, "pct": pct, "passed": passed, "text": text})
    return {"cohort_size": len(others), "beats_pct": beats,
            "text": f"Your score beats {beats}% of neatHack repos we've checked", "checks": checks}

content.content:
// Typed client for the PreJudge API. Network failures and HTTP errors are kept apart so the
// UI can tell "can't reach the server" from "the server said no".

export type Status = 'pass' | 'warn' | 'fail' | 'unverified'

export interface Step {
  name: string
  status: 'ok' | 'failed' | 'skipped'
  detail: string
  error_kind: string | null
  duration_ms: number
}

export interface Check {
  id: string
  category: string
  title: string
  status: Status
  detail: string
  evidence: string[]
  data?: Record<string, unknown>
}

export interface ScoreItem {
  id: string
  title: string
  status: string
  detail: string
  credit: number
  points: number
  max_points: number
  estimated: boolean
}

export interface Category {
  id: string
  weight: number
  max_points: number
  points: number
  not_scored?: boolean // nothing in it could be checked: left out, total rescaled
  items: ScoreItem[]
}

export interface Score {
  score: number
  max: number
  gated: boolean
  gate_reason: string | null
  estimated_points: number
  scored_max?: number // < 100 when a category was left out
  categories: Category[]
}

export interface Fix {
  check_id: string
  title: string
  points: number
  fix: string
}

export interface Verdict {
  roast: string
  fixes: Fix[]
  best_thing: string
  style?: string
  source: 'llm' | 'template'
  roast_source?: 'llm' | 'template' // template = the AI's roast failed the fact check
}

export interface Evidence {
  ref: string
  note?: string
}

export interface Claim {
  claim_id: string
  claim: string
  quote?: string
  category?: string
  status: 'verified' | 'unverified' | 'contradicted'
  evidence: Evidence[]
  reason: string
}

export interface Report {
  audit_id: string
  repo_url: string
  repo: { full_name: string; default_branch: string; stars?: number } | null
  head_sha?: string
  checks: Check[]
  score: Score
  verdict: Verdict
  phase: 'quick' | 'complete'
  agent?: {
    claims: Claim[]
    estimates: Record<string, { score: number; evidence: string[]; reason: string }>
    injection: { detected: boolean; deterministic?: string[]; reported_by_llm?: string[] }
  }
  timing_ms?: Record<string, number>
}

export interface QueueInfo {
  lane: 'quick' | 'deep'
  position: number
  estimated_wait_s: number
  waiting_for_budget: boolean
}

export interface Audit {
  id: string
  repo_url: string
  status: 'queued' | 'quick_ready' | 'complete' | 'failed'
  phases: { quick: string; deep: string }
  queue: QueueInfo | null
  cached: boolean
  steps: Step[]
  result: Report | null
  error: string | null
}

export interface Stats {
  total_audits: number
  completed_audits: number
  budget_state: 'normal' | 'busy' | 'cooling'
  deep_queue: number
  deep_wait_s: number
  llm_mode: string
}

export interface Example {
  id: string
  repo: string
  score: number | null
  roast: string | null
  style: string | null
}

export class ApiError extends Error {
  status: number
  network: boolean
  constructor(message: string, status = 0, network = false) {
    super(message)
    this.status = status
    this.network = network
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response
  try {
    res = await fetch(path, {
      ...init,
      headers: { 'Content-Type': 'application/json', ...(init?.headers ?? {}) },
    })
  } catch {
    throw new ApiError("Can't reach PreJudge right now.", 0, true)
  }
  if (!res.ok) {
    let detail = res.statusText
    try {
      const body = await res.json()
      detail = typeof body.detail === 'string' ? body.detail : detail
    } catch {
      /* not JSON */
    }
    throw new ApiError(detail, res.status)
  }
  return res.json() as Promise<T>
}

export const api = {
  createAudit: (repo_url: string) =>
    request<{ id: string; status: string; cached: boolean }>('/api/audits', {
      method: 'POST',
      body: JSON.stringify({ repo_url }),
    }),
  getAudit: (id: string) => request<Audit>(`/api/audits/${encodeURIComponent(id)}`),
  requestDeep: (id: string) =>
    request<{ status: string; queue: QueueInfo | null }>(`/api/audits/${encodeURIComponent(id)}/deep`, {
      method: 'POST',
    }),
  feedback: (id: string, check_id: string, note: string) =>
    request<{ ok: boolean }>(`/api/audits/${encodeURIComponent(id)}/feedback`, {
      method: 'POST',
      body: JSON.stringify({ check_id, is_wrong: true, note }),
    }),
  requestRemoval: (id: string, reason: string) =>
    request<{ ok: boolean; hidden: boolean }>(`/api/audits/${encodeURIComponent(id)}/removal`, {
      method: 'POST',
      body: JSON.stringify({ reason }),
    }),
  stats: () => request<Stats>('/api/stats'),
  examples: () => request<Example[]>('/api/examples'),
}

// A bare per-day counter (no cookies, nothing about the viewer). Never blocks or throws.
export function countEvent(name: 'card_download' | 'share_x'): void {
  try {
    fetch('/api/events', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
      keepalive: true,
    }).catch(() => {})
  } catch {
    /* counting is best-effort */
  }
}

const GITHUB_URL = /^(https?:\/\/)?(www\.)?github\.com\/[A-Za-z0-9-]+\/[A-Za-z0-9._-]+\/?(\.git)?$|^[A-Za-z0-9-]+\/[A-Za-z0-9._-]+$/

export function looksLikeRepo(input: string): boolean {
  return GITHUB_URL.test(input.trim())
}

export function shareUrl(id: string): string {
  const base = (import.meta.env.VITE_SHARE_BASE as string | undefined) ?? window.location.origin
  return `${base.replace(/\/$/, '')}/r/${id}`
}
import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { BrowserRouter, Route, Routes } from 'react-router-dom'
import './index.css'
import Home from './pages/Home.tsx'
import AuditPage from './pages/Audit.tsx'
import NotFound from './pages/NotFound.tsx'

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/a/:id" element={<AuditPage />} />
        <Route path="*" element={<NotFound />} />
      </Routes>
    </BrowserRouter>
  </StrictMode>,
)
import { useState } from 'react'
import { api, ApiError, type Audit, type Stats } from '../api'
import { formatWait } from '../labels'

// "Run deep check": queue the claim verification, then show position and ETA until it's done.
export default function DeepCheck({ audit, stats, onQueued }: { audit: Audit; stats: Stats | null; onQueued: () => void }) {
  const [error, setError] = useState<string | null>(null)
  const [sending, setSending] = useState(false)
  const deep = audit.phases.deep

  if (audit.status === 'complete') return null
  if (deep === 'skipped') return null

  if (['queued', 'running', 'waiting_budget'].includes(deep)) {
    const q = audit.queue
    let msg = 'Deep check queued…'
    if (deep === 'running') msg = 'Deep check running: reading the code and judging every claim…'
    else if (deep === 'waiting_budget' || q?.waiting_for_budget)
      msg = "Waiting for the judge models' daily budget. Your spot is saved; this page updates itself."
    else if (q) msg = `Deep check queued: position ${q.position}, ${formatWait(q.estimated_wait_s)}`
    return (
      <section className="panel deep-panel" data-testid="deep-status">
        <span className="spinner" aria-hidden /> <span>{msg}</span>
      </section>
    )
  }

  const run = async () => {
    setSending(true)
    setError(null)
    try {
      await api.requestDeep(audit.id)
      onQueued()
    } catch (e) {
      setError(e instanceof ApiError && e.network ? "Can't reach PreJudge. Try again?" : (e as Error).message)
    } finally {
      setSending(false)
    }
  }

  return (
    <section className="panel deep-panel">
      <div>
        <h2 className="panel-title">Want the full trial?</h2>
        <p className="muted">
          The deep check reads the code, verifies every README claim with file:line evidence and rescores.
          {stats?.budget_state === 'busy' && ` The queue is busy right now (${formatWait(stats.deep_wait_s)}).`}
          {stats?.budget_state === 'cooling' && " The judge models are cooling down; you'll be queued until they're back."}
          {deep === 'failed' && ' The last deep check failed; you can try again.'}
        </p>
      </div>
      <button className="big-button" onClick={run} disabled={sending}>
        {sending ? 'Queuing…' : 'Run deep check'}
      </button>
      {error && <p className="inline-error">{error}</p>}
    </section>
  )
}
import { useCallback, useEffect, useRef, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { api, ApiError, type Audit, type Stats } from '../api'
import DeepCheck from '../components/DeepCheck'
import RemovalLink from '../components/RemovalLink'
import Result from '../components/Result'
import RoastCard from '../components/RoastCard'
import StepLog from '../components/StepLog'

const POLL_MS = 1500
const ACTIVE_DEEP = ['queued', 'running', 'waiting_budget']

function isActive(a: Audit | null): boolean {
  if (!a) return true
  return a.status === 'queued' || ACTIVE_DEEP.includes(a.phases.deep)
}

export default function AuditPage() {
  const { id = '' } = useParams()
  const [audit, setAudit] = useState<Audit | null>(null)
  const [stats, setStats] = useState<Stats | null>(null)
  const [notFound, setNotFound] = useState(false)
  const [removed, setRemoved] = useState(false)
  const [offline, setOffline] = useState(false)
  const [tick, setTick] = useState(0)
  const timer = useRef<number | undefined>(undefined)

  const poll = useCallback(async () => {
    try {
      const a = await api.getAudit(id)
      setAudit(a)
      setOffline(false)
      return a
    } catch (e) {
      if (e instanceof ApiError && e.status === 404) setNotFound(true)
      else if (e instanceof ApiError && e.status === 410) setRemoved(true)
      else setOffline(true)
      return null
    }
  }, [id])

  // Poll every 1.5s while anything is still running (quick phase or a requested deep check).
  useEffect(() => {
    let alive = true
    const loop = async () => {
      const a = await poll()
      if (!alive) return
      if (isActive(a) && !notFound && !removed) timer.current = window.setTimeout(loop, POLL_MS)
    }
    loop()
    return () => {
      alive = false
      window.clearTimeout(timer.current)
    }
  }, [poll, tick, notFound, removed])

  // Results pages stay out of search engines (Caddy also sends X-Robots-Tag for /a/*).
  useEffect(() => {
    const meta = document.createElement('meta')
    meta.name = 'robots'
    meta.content = 'noindex, nofollow'
    document.head.appendChild(meta)
    return () => meta.remove()
  }, [])

  useEffect(() => {
    api.stats().then(setStats).catch(() => {})
  }, [tick])

  if (removed)
    return (
      <main className="page narrow" data-testid="audit-removed">
        <h1 className="headline">This audit was removed.</h1>
        <p className="lede">
          It's hidden from public view at the owner's request. <Link to="/">Audit a repo</Link>.
        </p>
      </main>
    )

  if (notFound)
    return (
      <main className="page narrow">
        <h1 className="headline">No such audit.</h1>
        <p className="lede">
          That link doesn't match any roast. <Link to="/">Audit a repo</Link>.
        </p>
      </main>
    )

  const report = audit?.result
  const live = !audit || audit.status === 'queued'
  return (
    <main className="page">
      <nav className="topbar">
        <Link to="/" className="brand">🔥 PreJudge</Link>
        {audit && <span className="muted small topbar-repo">{audit.repo_url.replace(/^https?:\/\/(www\.)?github\.com\//, '')}</span>}
      </nav>

      {offline && (
        <p className="notice notice-bad" role="alert" data-testid="offline">
          Lost connection to PreJudge. Retrying…{' '}
          <button className="link-button" onClick={() => setTick((t) => t + 1)}>Retry now</button>
        </p>
      )}

      {audit?.status === 'failed' && (
        <section className="panel error-panel" data-testid="audit-failed">
          <h1 className="headline">The judge tripped.</h1>
          <p className="lede">Something went wrong on our side ({audit.error ?? 'unknown error'}). Your repo is fine.</p>
          <Link className="big-button" to="/">Try again</Link>
        </section>
      )}

      {audit?.queue?.lane === 'quick' && audit.status === 'queued' && audit.queue.position > 1 && (
        <p className="notice notice-warn">In line: {audit.queue.position - 1} audit(s) ahead of you.</p>
      )}

      {report && audit && audit.status !== 'failed' && (
        <>
          <Result audit={audit} />
          {!report.score.gated && <DeepCheck audit={audit} stats={stats} onQueued={() => setTick((t) => t + 1)} />}
          {!report.score.gated && (
            <RoastCard
              auditId={audit.id}
              repo={report.repo?.full_name ?? audit.repo_url}
              score={report.score.score}
              roast={report.verdict.roast}
              template={report.verdict.source === 'template'}
            />
          )}
        </>
      )}

      {audit && <StepLog steps={audit.steps} live={live || ACTIVE_DEEP.includes(audit.phases.deep)} />}
      {audit && <RemovalLink auditId={audit.id} onRemoved={() => setRemoved(true)} />}
      {!audit && !offline && <StepLog steps={[]} live />}
    </main>
  )
}

