import { toPng } from 'html-to-image'
import { useRef, useState } from 'react'
import { countEvent, shareUrl } from '../api'
import { scoreTone } from '../labels'

interface Props {
  auditId: string
  repo: string
  score: number | null
  roast: string
  template: boolean
}

const SITE = (import.meta.env.VITE_SITE_NAME as string | undefined) ?? window.location.host

// 1200x630 card rendered at full size and shown scaled; html-to-image exports the full-size node.
export default function RoastCard({ auditId, repo, score, roast, template }: Props) {
  const cardRef = useRef<HTMLDivElement>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const download = async () => {
    if (!cardRef.current) return
    setBusy(true)
    setError(null)
    try {
      const url = await toPng(cardRef.current, { width: 1200, height: 630, pixelRatio: 1, cacheBust: true })
      const a = document.createElement('a')
      a.href = url
      a.download = `prejudge-${repo.replace('/', '-')}.png`
      a.click()
      countEvent('card_download')
    } catch {
      setError("Couldn't make the image. Try again?")
    } finally {
      setBusy(false)
    }
  }

  const short = roast.length > 150 ? roast.slice(0, 147).trimEnd() + '…' : roast
  const tweet = `PreJudge roasted ${repo}: ${score ?? '?'}/100 🔥 "${short}" #neatHack`
  const xHref = `https://twitter.com/intent/tweet?text=${encodeURIComponent(tweet)}&url=${encodeURIComponent(shareUrl(auditId))}`

  return (
    <section className="panel card-panel">
      <h2 className="panel-title">Roast card</h2>
      <div className="card-frame">
        <div className="card-scale">
          <div className="roast-card" ref={cardRef} data-testid="roast-card">
            <div className="rc-stripe" />
            <div className="rc-head">
              <span className="rc-brand">PREJUDGE</span>
              <span className="rc-sub">roasted before the judges</span>
              <span className="rc-tag">#neatHack</span>
            </div>
            <div className="rc-body">
              <div className={`rc-score tone-${scoreTone(score)}`}>
                <span className="rc-num">{score ?? '?'}</span>
                <span className="rc-of">/ 100</span>
              </div>
              <p className={`rc-roast ${roast.length > 260 ? 'rc-roast-long' : ''}`}>“{roast}”</p>
            </div>
            {template && <div className="rc-note">quick facts mode: full roast coming later</div>}
            <div className="rc-foot">
              <span className="rc-repo">{repo}</span>
              <span className="rc-site">{SITE}</span>
            </div>
          </div>
        </div>
      </div>
      <div className="button-row">
        <button className="big-button" onClick={download} disabled={busy}>
          {busy ? 'Rendering…' : 'Download PNG'}
        </button>
        <a className="big-button x-button" href={xHref} target="_blank" rel="noopener noreferrer"
           onClick={() => countEvent('share_x')}>
          Share on X
        </a>
      </div>
      {error && <p className="inline-error">{error}</p>}
    </section>
  )
}
import type { Audit, Check, Claim, Report } from '../api'
import { evidenceLink } from '../evidence'
import { CATEGORY_LABELS, CHECK_STATUS, CLAIM_STATUS, scoreTone } from '../labels'
import FeedbackButton from './FeedbackButton'

function EvidenceRefs({ refs, report }: { refs: string[]; report: Report }) {
  if (!refs.length) return null
  const repo = report.repo?.full_name
  return (
    <ul className="evidence">
      {refs.map((ref, i) => {
        // report.head_sha is a tree sha, not a commit: link files on the default branch
        const l = evidenceLink(ref, repo, report.repo?.default_branch)
        return (
          <li key={i}>
            {l.href ? (
              <a href={l.href} target="_blank" rel="noopener noreferrer">
                {l.text}
              </a>
            ) : (
              <code>{l.text}</code>
            )}
          </li>
        )
      })}
    </ul>
  )
}

function ScoreBlock({ report, deep }: { report: Report; deep: boolean }) {
  const s = report.score
  // Estimates only come from the deep check; before that (or if the LLM was out) the scoring
  // code fills in neutral defaults, and we say so instead of crediting "the AI".
  const placeholders = s.categories.some((c) =>
    c.items.some((i) => i.estimated && /unavailable|neutral/i.test(i.detail)))
  return (
    <section className="panel score-panel">
      <div className={`score-big tone-${scoreTone(s.score)}`} data-testid="score">
        <span className="score-num">{s.score}</span>
        <span className="score-of">/ 100</span>
      </div>
      <div className="score-side">
        <h1 className="repo-name">{report.repo?.full_name ?? report.repo_url}</h1>
        <div className="badges">
          {deep ? (
            <span className="badge badge-good" data-testid="deep-badge">Deep check complete</span>
          ) : (
            <span className="badge">Quick check</span>
          )}
          {s.scored_max != null && s.scored_max < 100 && (
            <span className="badge badge-muted" data-testid="rescaled-badge">
              Scored on the {s.scored_max} points we could check, scaled to 100
            </span>
          )}
          {s.estimated_points > 0 && (
            <span className="badge badge-muted" data-testid="estimate-badge">
              {placeholders
                ? `${s.estimated_points} pts are neutral placeholders until the deep check`
                : `${s.estimated_points} pts estimated by the AI (capped)`}
            </span>
