import os, re, io, tarfile, httpx, yaml
from dotenv import load_dotenv; load_dotenv(".env")
tok=os.environ.get("GITHUB_TOKEN"); H={"Authorization":f"Bearer {tok}"} if tok else {}
urls=yaml.safe_load(open("evals/private/repos.yaml"))
PATS={"video":r"youtu\.?be|youtube\.com|loom\.com|vimeo\.com|drive\.google\.com/[^\s)]*|x\.com/[^\s)]*/video|\.mp4\b",
      "cfo":r"cfo\.ai[^\s)\"']*","trace":r"neatlogs\.com/[^\s)\"']*|neatlogs[^\n]{0,40}\.(png|jpg|gif)",
      "before_after":r"\bbefore\b[^\n]{0,80}\bafter\b|baseline[^\n]{0,60}(improv|→|->)","posts":r"x\.com/\w+/status|twitter\.com/\w+/status|linkedin\.com/(posts|feed)|#neathack"}
for rid,url in urls.items():
    full=url.split("github.com/")[1].removesuffix(".git").strip("/")
    with httpx.Client(headers=H,follow_redirects=True,timeout=60) as c:
        data=c.get(f"https://api.github.com/repos/{full}/tarball").content
    files={}
    with tarfile.open(fileobj=io.BytesIO(data)) as tf:
        for m in tf:
            if m.isfile() and m.size<400_000 and not re.search(r"node_modules|\.lock|package-lock|\.(png|jpg|gif|ico|woff|svg|pdf)$",m.name):
                try: files[m.name.split("/",1)[1]]=tf.extractfile(m).read().decode("utf-8","ignore")
                except Exception: pass
    names=list(files)
    print(f"=== {rid}: {len(files)} text files; images/docs of interest:",[n for n in names if re.search(r"(?i)evidence|screenshot|trace|cfo|business|demo",n)][:8])
    readme=next((files[n] for n in names if n.lower()=="readme.md"),"")
    for k,p in PATS.items():
        inr=sorted(set(m.group(0)[:70] for m in re.finditer(p,readme,re.I)))[:4]
        other=sorted({n for n in names if n.lower()!="readme.md" and re.search(p,files[n],re.I)})[:5]
        print(f"   {k:12} README:{inr}  other files:{other}")
EOF

